CREATE USER api_readonly_user IDENTIFIED WITH sha256_password SETTINGS use_uncompressed_cache = true, max_threads = 48;
GRANT dictGet ON default.ability_items_dict TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.active_matches TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.game_stats_agg TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.hero_stats_agg_all_v2 TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.hero_stats_agg_v2 TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.heroes TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.item_cohort_stats_net_worth_agg_v2 TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.item_cohort_stats_time_agg_v2 TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.item_enemy_stats_agg TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.item_stats_agg_v2 TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.items TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.lane_matchups TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.match_player TO api_readonly_user;
GRANT SHOW TABLES, SELECT(cluster_id, created_at, failed_at, `failed_at.null`, match_id, metadata_salt, replay_salt, `replay_salt.null`, verified_at, `verified_at.null`), SHOW COLUMNS(cluster_id, created_at, failed_at, match_id, metadata_salt, replay_salt, verified_at) ON default.match_salts TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.player_match_history TO api_readonly_user;
GRANT SELECT ON default.player_match_roster TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.player_match_stats TO api_readonly_user;
GRANT SHOW TABLES, SHOW COLUMNS, SHOW DICTIONARIES, SELECT ON default.player_performance_curve_agg_v2 TO api_readonly_user;
GRANT SELECT ON default.steam_profiles TO api_readonly_user;
GRANT dictGet ON default.upgrade_items_dict TO api_readonly_user;
